package com.example.onlineshop.catalog.api;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*; import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
import com.fasterxml.jackson.databind.*; import java.nio.file.*; import java.util.*; import org.junit.jupiter.api.*; import org.springframework.beans.factory.annotation.Autowired; import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc; import org.springframework.boot.test.context.SpringBootTest; import org.springframework.test.context.DynamicPropertyRegistry; import org.springframework.test.context.DynamicPropertySource; import org.springframework.test.web.servlet.MockMvc; import org.testcontainers.junit.jupiter.Container; import org.testcontainers.junit.jupiter.Testcontainers; import org.testcontainers.postgresql.PostgreSQLContainer;
@Tag("docker") @Testcontainers(disabledWithoutDocker=false) @SpringBootTest @AutoConfigureMockMvc class CatalogApiTest {
 @Container static final PostgreSQLContainer postgres=new PostgreSQLContainer("postgres:16.6-alpine");
 @DynamicPropertySource static void database(DynamicPropertyRegistry r){r.add("spring.datasource.url",postgres::getJdbcUrl);r.add("spring.datasource.username",postgres::getUsername);r.add("spring.datasource.password",postgres::getPassword);}
 @Autowired MockMvc mvc;
 @Test void createListDetailAndProblems() throws Exception {var body="{\"name\":\"Synthetic Tea\",\"description\":\"Fixture\",\"price\":\"12.30\",\"currency\":\"NZD\",\"stockQuantity\":4}";var json=mvc.perform(post("/api/v1/products").contentType("application/json").content(body)).andExpect(status().isCreated()).andExpect(jsonPath("$.price").value("12.30")).andReturn().getResponse().getContentAsString();var id=json.replaceAll(".*\\\"id\\\":\\\"([^\\\"]+).*","$1");mvc.perform(get("/api/v1/products/"+id)).andExpect(status().isOk()).andExpect(jsonPath("$.id").value(id));mvc.perform(get("/api/v1/products")).andExpect(status().isOk()).andExpect(jsonPath("$.totalElements").value(1));mvc.perform(post("/api/v1/products").contentType("application/json").content("{}" )).andExpect(status().isUnprocessableEntity()).andExpect(content().contentType("application/problem+json"));mvc.perform(get("/api/v1/products/00000000-0000-0000-0000-000000000000")).andExpect(status().isNotFound()).andExpect(jsonPath("$.code").value("PRODUCT_NOT_FOUND"));}
 @Test void malformedIs400() throws Exception {mvc.perform(post("/api/v1/products").contentType("application/json").content("{" )).andExpect(status().isBadRequest());}
 @Test void frameworkErrorsUseProblemDetails() throws Exception {mvc.perform(put("/api/v1/products").contentType("application/json").content("{}" )).andExpect(status().isMethodNotAllowed()).andExpect(content().contentType("application/problem+json")).andExpect(jsonPath("$.code").value("METHOD_NOT_ALLOWED"));mvc.perform(post("/api/v1/products").contentType("application/xml").content("<product/>" )).andExpect(status().isUnsupportedMediaType()).andExpect(content().contentType("application/problem+json")).andExpect(jsonPath("$.code").value("UNSUPPORTED_MEDIA_TYPE"));mvc.perform(get("/api/v1/products/x/y")).andExpect(status().isNotFound()).andExpect(content().contentType("application/problem+json")).andExpect(jsonPath("$.code").value("RESOURCE_NOT_FOUND"));}
 @Test void publishesApprovedOpenApiResponses() throws Exception {mvc.perform(get("/v3/api-docs")).andExpect(status().isOk()).andExpect(jsonPath("$.paths['/api/v1/products'].post.responses['201']").exists()).andExpect(jsonPath("$.paths['/api/v1/products'].post.responses['400'].content['application/problem+json']").exists()).andExpect(jsonPath("$.paths['/api/v1/products'].post.responses['422'].content['application/problem+json']").exists()).andExpect(jsonPath("$.paths['/api/v1/products/{productId}'].get.responses['404'].content['application/problem+json']").exists());}
 @Test void checkedOpenApiPathsAndResponsesMatchRuntime() throws Exception {var mapper=new ObjectMapper();JsonNode runtime=mapper.readTree(mvc.perform(get("/v3/api-docs")).andReturn().getResponse().getContentAsString());JsonNode checked=mapper.readTree(Paths.get("../../tests/contracts/catalog-api.json").toFile());Assertions.assertEquals(fieldNames(checked.path("paths")),fieldNames(runtime.path("paths")));Assertions.assertEquals(fieldNames(checked.path("components").path("schemas")),fieldNames(runtime.path("components").path("schemas")));for(String path:fieldNames(checked.path("paths"))){for(String method:fieldNames(checked.path("paths").path(path))){Assertions.assertEquals(fieldNames(checked.path("paths").path(path).path(method).path("responses")),fieldNames(runtime.path("paths").path(path).path(method).path("responses")),path+" "+method);}}}
 private static Set<String> fieldNames(JsonNode node){var names=new TreeSet<String>();node.fieldNames().forEachRemaining(names::add);return names;}
}
